('kim-mex-construction-investment-coltd-cache-global_settings_en','a:4:{s:7:\"profile\";a:14:{s:19:\"registration_number\";N;s:12:\"founded_date\";N;s:5:\"phone\";s:15:\"+855 23 884 604\";s:5:\"email\";s:18:\"info@kimmex.com.kh\";s:15:\"google_maps_url\";s:309:\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3908.667785689154!2d104.89350269999998!3d11.575656499999992!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31095176fe4b5e51%3A0x844dbeef5ee9d25b!2sKim%20mex%20Construction%20%26%20Investment%20Co.%2Cltd!5e0!3m2!1skm!2skh!4v1775701743611!5m2!1skm!2skh\";s:4:\"logo\";N;s:7:\"favicon\";s:0:\"\";s:8:\"facebook\";s:48:\"https://www.facebook.com/kimmex168/?locale=km_KH\";s:8:\"linkedin\";s:93:\"https://www.linkedin.com/company/kim-mex-construction-investment-co-ltd/?originalSubdomain=kh\";s:7:\"youtube\";N;s:9:\"instagram\";N;s:8:\"telegram\";N;s:2:\"en\";a:5:{s:12:\"company_name\";s:6:\"KIMMEX\";s:13:\"website_title\";s:0:\"\";s:7:\"tagline\";s:34:\"CONSTRUCTION & INVESTMENT CO.,LTD.\";s:7:\"address\";s:73:\"#54, St.590, Sangkat Boeung Kok II, Khan Toul Kork, Phnom Penh, Cambodia.\";s:13:\"working_hours\";s:28:\"Mon - Fri: 8:00 AM - 5:30 PM\";}s:2:\"km\";a:5:{s:12:\"company_name\";s:21:\"គីមម៉ិច\";s:13:\"website_title\";s:0:\"\";s:7:\"tagline\";s:74:\"សំណង់ និងវិនិយោគ ខូអិលធីឌី\";s:7:\"address\";s:212:\"ផ្ទះលេខ៥៤ ផ្លូវ៥៩០ សង្កាត់បឹងកក់២ ខណ្ឌទួលគោក រាជធានីភ្នំពេញ ប្រទេសកម្ពុជា។\";s:13:\"working_hours\";s:80:\"ច័ន្ទ - សុក្រៈ 8:00 ព្រឹក - 5:30 ល្ងាច\";}}s:5:\"brand\";a:6:{s:13:\"company_story\";s:382:\"Established in 1999, Kim Mex Construction & Investment Co., Ltd. is a deeply respected and duly registered enterprise in the Kingdom of Cambodia. Over more than 25 years, we have evolved from a specialized engineering firm into a premier multi-disciplinary construction partner, delivering iconic infrastructure that stands the test of time while elevating the communities we serve.\";s:11:\"ceo_message\";s:159:\"<p>Construction is not just about concrete and steel. It is about building trust, fostering communities, and leaving a legacy that stands the test of time.</p>\";s:7:\"mission\";s:135:\"To bridge the gap between concept and reality through exceptional precision, military-grade safety, and sustainable building practices.\";s:6:\"vision\";s:141:\"To be the most trusted and innovative construction partner in Cambodia, setting the benchmark for excellence in architecture and engineering.\";s:4:\"goal\";s:136:\"To maintain long-term leadership in the Cambodian market through talent development, CMS investment, and a zero-accident safety records.\";s:11:\"values_list\";a:7:{i:0;a:4:{s:5:\"title\";s:7:\"HONESTY\";s:11:\"description\";s:71:\"Unwavering transparency and ethics in every contract and communication.\";s:4:\"icon\";s:13:\"lucide-shield\";s:5:\"image\";N;}i:1;a:4:{s:5:\"title\";s:10:\"DISCIPLINE\";s:11:\"description\";s:67:\"Military-grade precision and adherence to strict project timelines.\";s:4:\"icon\";s:12:\"lucide-award\";s:5:\"image\";N;}i:2;a:4:{s:5:\"title\";s:13:\"QUALITY FIRST\";s:11:\"description\";s:67:\"Rigorous international standards applied from foundation to finish.\";s:4:\"icon\";s:21:\"lucide-check-circle-2\";s:5:\"image\";N;}i:3;a:4:{s:5:\"title\";s:18:\"CULTURE OF SHARING\";s:11:\"description\";s:60:\"Fostering knowledge exchange to empower our local workforce.\";s:4:\"icon\";s:14:\"lucide-share-2\";s:5:\"image\";N;}i:4;a:4:{s:5:\"title\";s:23:\"CREATIVITY & INNOVATION\";s:11:\"description\";s:72:\"Pioneering new construction techniques and modern architectural designs.\";s:4:\"icon\";s:16:\"lucide-lightbulb\";s:5:\"image\";N;}i:5;a:4:{s:5:\"title\";s:27:\"RESPECT THE VALUE OF PEOPLE\";s:11:\"description\";s:75:\"Putting the safety and dignity of our staff at the heart of our operations.\";s:4:\"icon\";s:12:\"lucide-users\";s:5:\"image\";N;}i:6;a:4:{s:5:\"title\";s:18:\"SENSE OF OWNERSHIP\";s:11:\"description\";s:79:\"Every team member takes personal pride and responsibility for every brick