('kim-mex-construction-investment-coltd-cache-global_settings_km','a:4:{s:7:\"profile\";a:14:{s:19:\"registration_number\";N;s:12:\"founded_date\";N;s:5:\"phone\";s:15:\"+855 23 884 604\";s:5:\"email\";s:18:\"info@kimmex.com.kh\";s:15:\"google_maps_url\";s:309:\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3908.667785689154!2d104.89350269999998!3d11.575656499999992!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31095176fe4b5e51%3A0x844dbeef5ee9d25b!2sKim%20mex%20Construction%20%26%20Investment%20Co.%2Cltd!5e0!3m2!1skm!2skh!4v1775701743611!5m2!1skm!2skh\";s:4:\"logo\";N;s:7:\"favicon\";s:0:\"\";s:8:\"facebook\";s:48:\"https://www.facebook.com/kimmex168/?locale=km_KH\";s:8:\"linkedin\";s:93:\"https://www.linkedin.com/company/kim-mex-construction-investment-co-ltd/?originalSubdomain=kh\";s:7:\"youtube\";N;s:9:\"instagram\";N;s:8:\"telegram\";N;s:2:\"en\";a:5:{s:12:\"company_name\";s:6:\"KIMMEX\";s:13:\"website_title\";s:0:\"\";s:7:\"tagline\";s:34:\"CONSTRUCTION & INVESTMENT CO.,LTD.\";s:7:\"address\";s:73:\"#54, St.590, Sangkat Boeung Kok II, Khan Toul Kork, Phnom Penh, Cambodia.\";s:13:\"working_hours\";s:28:\"Mon - Fri: 8:00 AM - 5:30 PM\";}s:2:\"km\";a:5:{s:12:\"company_name\";s:21:\"គីមម៉ិច\";s:13:\"website_title\";s:0:\"\";s:7:\"tagline\";s:74:\"សំណង់ និងវិនិយោគ ខូអិលធីឌី\";s:7:\"address\";s:212:\"ផ្ទះលេខ៥៤ ផ្លូវ៥៩០ សង្កាត់បឹងកក់២ ខណ្ឌទួលគោក រាជធានីភ្នំពេញ ប្រទេសកម្ពុជា។\";s:13:\"working_hours\";s:80:\"ច័ន្ទ - សុក្រៈ 8:00 ព្រឹក - 5:30 ល្ងាច\";}}s:5:\"brand\";a:6:{s:13:\"company_story\";s:1047:\"បង្កើតឡើងក្នុងឆ្នាំ 1999 ក្រុមហ៊ុន គីម ម៉ិច ខនស្ត្រាសិន និង អ៊ិនវេសមេន ខូអិលធីឌី គឺជាសហគ្រាសដែលមានការចុះបញ្ជីត្រឹមត្រូវ និងគោរពយ៉ាងជ្រាលជ្រៅនៅក្នុងព្រះរាជាណាចក្រកម្ពុជា។ ក្នុងរយៈពេលជាង 25 ឆ្នាំ យើងបានវិវត្តន៍ពីក្រុមហ៊ុនវិស្វកម្មឯកទេសទៅជាដៃគូសាងសង់ពហុវិន័យឈានមុខគេ ដោយផ្តល់នូវហេដ្ឋារចនាសម្ព័ន្ធរូបសញ្ញាដែលឈរលើការសាកល្បងនៃពេលវេលាខណៈពេលដែលលើកកម្ពស់សហគមន៍ដែលយើងបម្រើ។\";s:11:\"ceo_message\";s:437:\"<p>ការ​សាង​សង់​មិន​មែន​ត្រឹម​តែ​បេតុង និង​ដែក​នោះ​ទេ។ វានិយាយអំពីការកសាងទំនុកចិត្ត ពង្រឹងសហគមន៍ និងការបន្សល់ទុកនូវកេរដំណែលដែលឈរលើការសាកល្បងនៃពេលវេលា។</p>\";s:7:\"mission\";s:355:\"ដើម្បីភ្ជាប់គម្លាតរវាងគំនិត និងការពិត តាមរយៈភាពជាក់លាក់ពិសេស សុវត្ថិភាពកម្រិតយោធា និងការអនុវត្តការកសាងប្រកបដោយនិរន្តរភាព។\";s:6:\"vision\";s:423:\"ដើម្បីធ្វើជាដៃគូសាងសង់ប្រកបដោយភាពជឿជាក់ និងច្នៃប្រឌិតបំផុតនៅក្នុងប្រទេសកម្ពុជា កំណត់ស្តង់ដារសម្រាប់ឧត្តមភាពក្នុងវិស័យស្ថាបត្យកម្ម និងវិស្វកម្ម។\";s:4:\"goal\";s:403:\"ដើម្បីរក្សាភាពជាអ្នកដឹកនាំរយៈពេលវែងនៅក្នុងទីផ្សារកម្ពុជា តាមរយៈការអភិវឌ្ឍន៍ទេពកោសល្យ ការវិនិយោគ CMS និងកំណត់ត្រាសុវត្ថិភាពគ្មានគ្រោះថ្នាក់។\";s:11:\"values_list\";a:7:{i:0;a:4:{s:5:\"title\";s:39:\"ភាពស្មោះត្រង់\";s:11:\"description\";s:212:\"តម្លាភាព និងក្រមសីលធម៌មិនផ្លាស់ប្តូរនៅក្នុងរាល់កិច្ចសន្យា និងទំនាក់ទំនង។\";s:4:\"icon\";s:13:\"lucide-shield\";s:5:\"image\";N;}i:1;a:4:{s:5:\"title\";s:15:\"វិន័យ\";s:11:\"description\";s:220:\"ភាពជាក់លាក់ថ្នាក់យោធា និងការប្រកាន់ខ្ជាប់នូវការកំណត់ពេលវេលាគម្រោងដ៏តឹងរឹង។\";s:4:\"icon\";s:12:\"lucide-award\";s:5:\"image\";N;}i:2;a:4:{s:5:\"title\";s:33:\"គុណភាពដំបូង\";s:11:\"description\";s:181:\"ស្តង់ដារអន្តរជាតិយ៉ាងម៉ត់ចត់ អនុវត្តតាំងពីមូលដ្ឋានរហូតដល់ចប់។\";s:4:\"icon\";s:21:\"lucide-check-circle-2\";s:5:\"image\";N;}i:3;a:4:{s:5:\"title\";s:60:\"វប្បធម៌នៃការចែករំលែក\";s:11:\"description\";s:211:\"ជំរុញការផ្លាស់ប្តូរចំណេះដឹង ដើម្បីពង្រឹងកម្លាំងពលកម្មក្នុងស្រុករបស់យើង។\";s:4:\"icon\";s:14:\"lucide-share-2\";s:5:\"image\";N;}i:4;a:4:{s:5:\"title\";s:94:\"ភាពច្នៃប្រឌិត និងគំនិតច្នៃប្រឌិត\";s:11:\"description\";s:175:\"ត្រួសត្រាយលើបច្ចេកទេសសំណង់ថ្មី និងការរចនាស្ថាបត្យកម្មទំនើប។\";s:4:\"icon\";s:16:\"lucide-lightbulb\";s:5:\"image\";N;}i:5;a:4:{s:5:\"title\";s:57:\"គោរពតម្លៃរបស់មនុស្ស\";s:11:\"description\";s:266:\"ការដាក់សុវត្ថិភាព និងសេចក្តីថ្លៃថ្នូររបស់បុគ្គលិករបស់យើង គឺជាបេះដូងនៃប្រតិបត្តិការរបស់យើង។\";s:4:\"icon\";s:12:\"lucide-users\";s:5:\"image\";N;}i:6;a:4:{s:5:\"title\";s:63:\"អារម្មណ៍នៃភាពជាម្ចាស់\";s:11:\"description\";s:226:\"សមាជិកក្រុមនីមួយៗមានមោទនភាព និងទំនួលខុសត្រូវផ្ទាល់ខ្លួនចំពោះរាល់ឥដ្ឋដែលដាក់។\"