('kim-mex-construction-investment-coltd-cache-home_services_array_en','a:4:{i:0;a:5:{s:4:\"icon\";s:15:\"lucide-pen-tool\";s:5:\"title\";s:14:\"Design & Build\";s:4:\"desc\";s:136:\"A seamless integration of architectural creativity and engineering precision. We handle the entire lifecycle from concept to completion.\";s:8:\"features\";a:3:{i:0;s:0:\"\";i:1;s:0:\"\";i:2;s:0:\"\";}s:4:\"slug\";s:12:\"design-build\";}i:1;a:5:{s:4:\"icon\";s:13:\"lucide-hammer\";s:5:\"title\";s:12:\"Construction\";s:4:\"desc\";s:141:\"World-class building and civil engineering solutions. We deliver robust structures tailored to residential, commercial, and industrial needs.\";s:8:\"features\";a:3:{i:0;s:0:\"\";i:1;s:0:\"\";i:2;s:0:\"\";}s:4:\"slug\";s:12:\"construction\";}i:2;a:5:{s:4:\"icon\";s:15:\"lucide-settings\";s:5:\"title\";s:18:\"Project Management\";s:4:\"desc\";s:153:\"Comprehensive oversight and strategic advisory ensuring on-time, on-budget delivery. We combine rigorous on-field management with technical and financ...\";s:8:\"features\";a:3:{i:0;s:0:\"\";i:1;s:0:\"\";i:2;s:0:\"\";}s:4:\"slug\";s:18:\"project-management\";}i:3;a:5:{s:4:\"icon\";s:12:\"lucide-truck\";s:5:\"title\";s:14:\"Infrastructure\";s:4:\"desc\";s:123:\"Developing critical infrastructure including roads, bridges, and public utilities. We build foundation for national growth.\";s:8:\"features\";a:3:{i:0;s:0:\"\";i:1;s:0:\"\";i:2;s:0:\"\";}s:4:\"slug\";s:14:\"infrastructure\";}}',1780514742),
('kim-mex-construction-investment-coltd-cache-home_testimonials_array_en','a:3:{i:0;a:4:{s:5:\"quote\";s:85:\"They delivered our commercial building ahead of schedule and with impeccable quality.\";s:6:\"rating\";i:5;s:6:\"author\";s:6:\"Sok V.\";s:4:\"role\";s:15:\"CEO, Alpha Corp\";}i:1;a:4:{s:5:\"quote\";s:93:\"The attention to detail and safety standards were outstanding during the water plant project.\";s:6:\"rating\";i:5;s:6:\"author\";s:8:\"Dr. Cham\";s:4:\"role\";s:26:\"Director of Infrastructure\";}i:2;a:4:{s:5:\"quote\";s:87:\"Highly professional team. They handled all the MEP complexities without a single delay.\";s:6:\"rating\";i:5;s:6:\"author\";s:9:\"Mr. Rithy\";s:4:\"role\";s:18:\"Property Developer\";}}',1780514742),
