('kim-mex-construction-investment-coltd-cache-project_show_data_project-01-mef-09_en','a:15:{s:2:\"id\";s:17:\"project-01-mef-09\";s:5:\"title\";s:42:\"Ministry of Economy Office Building MEF-09\";s:4:\"type\";s:10:\"Government\";s:8:\"location\";s:73:\"Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh\";s:6:\"status\";s:7:\"Ongoing\";s:4:\"date\";s:9:\"July 2026\";s:6:\"client\";s:31:\"Ministry of Economy and Finance\";s:10:\"built_area\";s:20:\"6 floors | 3,563 m²\";s:14:\"contract_value\";s:19:\"Contact for Details\";s:4:\"year\";s:19:\"May 2025 - Jul 2026\";s:9:\"heroImage\";s:31:\"/images/projects/mpt-office.jpg\";s:9:\"narrative\";a:5:{s:11:\"description\";s:205:\"<p>Ministry of Economy Office Building MEF-09 is a Kimmex construction project for Ministry of Economy and Finance, located in Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh.</p>\";s:10:\"background\";s:301:\"<p>The project was planned around the client requirements, site conditions, and construction schedule for Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh.</p><ul><li>Construction value: $3,650,000.00</li><li>Built area: 3,563 m²</li><li>Planned duration: 14 months</li></ul>\";s:10:\"objectives\";s:303:\"<ul><li>Deliver the project scope with practical coordination between client, design, and site teams.</li><li>Maintain construction quality, schedule discipline, and safe site execution.</li><li>Provide a durable facility that supports the operational needs of Ministry of Economy and Finance.</li></ul>\";s:14:\"design_concept\";s:208:\"<p>The design and construction approach focused on institutional function, public access, and long-term durability. Kimmex aligned execution with the documented scale, location, and schedule requirements.</p>\";s:21:\"engineering_narrative\";s:279:\"<p>Kimmex managed construction execution through practical sequencing, site coordination, and quality checks across the project lifecycle.</p><p>The work required coordination of resources, materials, and schedule milestones to keep delivery aligned with client expectations.</p>\";}s:5:\"scope\";s:294:\"<ul><li>Project owner: Ministry of Economy and Finance</li><li>Construction location: Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh</li><li>Construction value: $3,650,000.00</li><li>Built area: 3,563 m²</li><li>Floors: 6 floors</li><li>Duration: 14 months</li></ul>\";s:6:\"images\";a:3:{i:0;s:31:\"/images/projects/mpt-office.jpg\";i:1;s:32:\"/images/projects/Thumbnail-1.jpg\";i:2;s:32:\"/images/projects/Thumbnail-4.jpg\";}s:7:\"related\";a:3:{i:0;a:4:{s:2:\"id\";s:18:\"project-02-nbfsa-i\";s:5:\"title\";s:64:\"NBFSA-I Non-Banking Financial Services Authority Office Building\";s:4:\"type\";s:10:\"Government\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";}i:1;a:4:{s:2:\"id\";s:15:\"project-03-nspc\";s:5:\"title\";s:44:\"NSPC Social Security Council Office Building\";s:4:\"type\";s:10:\"Government\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";}i:2;a:4:{s:2:\"id\";s:25:\"project-04-smart-building\";s:5:\"title\";s:45:\"Royal University of Phnom Penh Smart Building\";s:4:\"type\";s:9:\"Education\";s:5:\"image\";s:32:\"/images/projects/Thumbnail-8.jpg\";}}}',1780514163),
('kim-mex-construction-investment-coltd-cache-project_show_data_project-01-mef-09_km','a:15:{s:2:\"id\";s:17:\"project-01-mef-09\";s:5:\"title\";s:94:\"អគារការិយាល័យក្រសួងសេដ្ឋកិច្ច MEF-09\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:8:\"location\";s:169:\"អគារលេខ៦០ ផ្លូវ៩២ សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ\";s:6:\"status\";s:7:\"Ongoing\";s:4:\"date\";s:9:\"July 2026\";s:6:\"client\";s:31:\"Ministry of Economy and Finance\";s:10:\"built_area\";s:20:\"6 floors | 3,563 m²\";s:14:\"contract_value\";s:90:\"ទំនាក់ទំនងសម្រាប់ព័ត៌មានលម្អិត\";s:4:\"year\";s:19:\"May 2025 - Jul 2026\";s:9:\"heroImage\";s:31:\"/images/projects/mpt-office.jpg\";s:9:\"narrative\";a:5:{s:11:\"description\";s:502:\"<p>អគារការិយាល័យក្រសួងសេដ្ឋកិច្ច MEF-09 គឺជាគម្រោងសាងសង់ គីមម៉ិច របស់ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ ដែលមានទីតាំងនៅអគារលេខ ៦០ ផ្លូវលេខ ៩២ សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ។</p>\";s:10:\"background\";s:605:\"<p>គម្រោងនេះត្រូវបានគ្រោងទុកជុំវិញតម្រូវការអតិថិជន លក្ខខណ្ឌការដ្ឋាន និងកាលវិភាគសាងសង់សម្រាប់អគារលេខ 60 ផ្លូវលេខ 92 សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ។</p><ul><li>តម្លៃសាងសង់៖ $3,650,000.00</li><li>ផ្ទៃដីសាងសង់៖ 3,563 m²</li><li>14li>Planned: រយៈពេល៖\";s:10:\"objectives\";s:789:\"<ul><li>ផ្តល់វិសាលភាពគម្រោងដោយមានការសម្របសម្រួលជាក់ស្តែងរវាងអតិថិជន ការរចនា និងក្រុមគេហទំព័រ។</li><li>រក្សាគុណភាពសំណង់ ការកំណត់កាលវិភាគ និងការអនុវត្តទីតាំងប្រកបដោយសុវត្ថិភាព។</li><li>ផ្តល់កន្លែងប្រើប្រាស់បានយូរ ដែលគាំទ្រដល់តម្រូវការប្រតិបត្តិការរបស់ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ។</li></ul>\";s:14:\"design_concept\";s:500:\"<p>វិធីសាស្រ្តនៃការរចនា និងការសាងសង់ផ្តោតលើមុខងារស្ថាប័ន ការចូលប្រើប្រាស់ជាសាធារណៈ និងយូរអង្វែង។ Kimmex បាន​តម្រឹម​ការ​ប្រតិបត្តិ​តាម​ខ្នាត​ឯកសារ ទីតាំង និង​តម្រូវការ​កាលវិភាគ។</p>\";s:21:\"engineering_narrative\";s:429:\"<p>Kimmex បានគ្រប់គ្រងការប្រតិបត្តិសំណង់តាមរយៈការអនុវត្តតាមលំដាប់លំដោយជាក់ស្តែង ការសំរបសំរួលទីតាំង និងការត្រួតពិនិត្យគុណភាពនៅទូទាំងវដ្តជីវិតរបស់គម្រោង។\";}s:5:\"scope\";s:572:\"<ul><li>ម្ចាស់គម្រោង: ក្រសួងសេដ្ខកិច្ច និង ហរិញ្ញវត្ថុ</li><li>ទីតាំងសាងសង់: អគារលេខ ៦០, ផ្លូវលេខ ៩២, សង្កាត់វត្តភ្នំ, ខណ្ឌដូនពេញ, រាជធានីភ្នំពេញ</li><li>តម្លៃសាងសង់: $3,650,000.00</li><li>ផ្ទៃក្រឡា: 3,563 m²</li><li>ចំនួនជាន់: 6ជាន់</li><li>រយៈពេល: 14 ខែ</li></ul>\";s:6:\"images\";a:3:{i:0;s:31:\"/images/projects/mpt-office.jpg\";i:1;s:32:\"/images/projects/Thumbnail-1.jpg\";i:2;s:32:\"/images/projects/Thumbnail-4.jpg\";}s:7:\"related\";a:3:{i:0;a:4:{s:2:\"id\";s:18:\"project-02-nbfsa-i\";s:5:\"title\";s:152:\"NBFSA-I អគារការិយាល័យអាជ្ញាធរសេវាហិរញ្ញវត្ថុមិនមែនធនាគារ\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";}i:1;a:4:{s:2:\"id\";s:15:\"project-03-nspc\";s:5:\"title\";s:122:\"អគារការិយាល័យក្រុមប្រឹក្សាសន្តិសុខសង្គម NSPC\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";}i:2;a:4:{s:2:\"id\";s:25:\"project-04-smart-building\";s:5:\"title\";s:96:\"សាកលវិទ្យាល័យភូមិន្ទភ្នំពេញ Smart Building\";s:4:\"type\";s:15:\"អប់រំ\";s:5:\"image\";s:32:\"/images/projects/Thumbnail-8.jpg\";}}}',1780514185),
