('kim-mex-construction-investment-coltd-cache-projects_index_data_km','a:4:{s:10:\"categories\";a:7:{i:0;s:21:\"ទាំងអស់\";i:1;s:15:\"អប់រំ\";i:2;s:27:\"សុខាភិបាល\";i:3;s:30:\"រដ្ឋាភិបាល\";i:4;s:70:\"ថាមពល និងប្រព័ន្ធសាធារណៈ\";i:5;s:54:\"ហេដ្ឋារចនាសម្ព័ន្ធ\";i:6;s:33:\"ពាណិជ្ជកម្ម\";}s:9:\"locations\";a:20:{i:0;s:21:\"ទាំងអស់\";i:1;s:210:\"សាខាវិទ្យាស្ថានពហុបច្ចេកទេស ផ្លូវសហព័ន្ធរុស្សី ខណ្ឌទួលគោក រាជធានីភ្នំពេញ\";i:2;s:174:\"ផ្លូវខេមិច សង្កាត់ព្រែកតាសិត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ។\";i:3;s:171:\"ភូមិតាតាស សង្កាត់ព្រែកតាសេក ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ។\";i:4;s:67:\"ក្រុងតាខ្មៅ ខេត្តកណ្តាល\";i:5;s:33:\"24 ខេត្តក្រុង\";i:6;s:149:\"ផ្លូវ21 សង្កាត់ទន្លេបាសាក់ ខណ្ឌចំការមន រាជធានីភ្នំពេញ\";i:7;s:110:\"សង្កាត់ឃ្មួញ ខណ្ឌសែនសុខ រាជធានីភ្នំពេញ\";i:8;s:186:\"មហាវិថីព្រះនរោត្តម សង្កាត់ទន្លេបាសាក់ ខណ្ឌចំការមន រាជធានីភ្នំពេញ\";i:9;s:113:\"ផ្លូវជាតិលេខ៥ ស្រុកក្រគរ ខេត្តពោធិ៍សាត់\";i:10;s:49:\"ក្រុងកែប ខេត្តកែប\";i:11;s:147:\"ផ្លូវសុធារស សង្កាត់ចតុមុខ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ\";i:12;s:165:\"ផ្លូវសុធារស សង្កាត់ទន្លេបាសាក់ ខណ្ឌចំការមន រាជធានីភ្នំពេញ\";i:13;s:150:\"ផ្លូវក្រមួនស សង្កាត់ស្រះចក ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ\";i:14;s:82:\"ស្រុកស្ទឹងហាវ ខេត្តព្រះសីហនុ\";i:15;s:92:\"ឃុំជ្រៃធំ ស្រុកស្អាង ខេត្តកណ្តាល\";i:16;s:140:\"សង្កាត់ព្រែកតាសិត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ\";i:17;s:142:\"ផ្លូវផែ ភូមិ៣ សង្កាត់៣ ខណ្ឌមិត្តភាព ក្រុងព្រះសីហនុ\";i:18;s:193:\"អគារលេខ១៦៨ ផ្លូវ៥៩៨ សង្កាត់ច្រាំងចំរេះ១ ខណ្ឌឬស្សីកែវ រាជធានីភ្នំពេញ\";i:19;s:169:\"អគារលេខ៦០ ផ្លូវ៩២ សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ\";}s:13:\"statusOptions\";a:4:{i:0;s:21:\"ទាំងអស់\";i:1;s:7:\"Ongoing\";i:2;s:9:\"Completed\";i:3;s:7:\"Planned\";}s:8:\"projects\";a:23:{i:0;a:8:{s:2:\"id\";s:25:\"project-23-ntti-tvet-park\";s:5:\"title\";s:145:\"ការសាងសង់សាលារៀន សិក្ខាសាលា និងអគារលំនៅដ្ឋាន (NTTI_TVET Park)\";s:8:\"featured\";b:0;s:8:\"location\";s:210:\"សាខាវិទ្យាស្ថានពហុបច្ចេកទេស ផ្លូវសហព័ន្ធរុស្សី ខណ្ឌទួលគោក រាជធានីភ្នំពេញ\";s:4:\"type\";s:15:\"អប់រំ\";s:6:\"status\";s:9:\"Completed\";s:5:\"image\";s:32:\"/images/projects/Thumbnail-8.jpg\";s:7:\"summary\";s:545:\"ការសាងសង់សាលារៀន សិក្ខាសាលា និងអគារលំនៅដ្ឋាន (NTTI_TVET Park) គឺជាគម្រោងសាងសង់ គីមម៉ិច របស់ក្រសួងការងារ ដែលមានទីតាំងនៅក្នុងបរិវេណវិទ្យាស្ថានពហុបច្ចេកទេស ផ្លូវសហព័ន្ធរុស្ស៊ី ខណ្ឌទួលគោក រាជធានីភ្នំពេញ។\";}i:1;a:8:{s:2:\"id\";s:10:\"project-22\";s:5:\"title\";s:224:\"ការ​សាងសង់​សាលា​ជាតិ​គយ និង​លំនៅឋាន​នៃ​អគ្គនាយកដ្ឋាន​គយ និង​រដ្ឋបាល​កម្ពុជា។\";s:8:\"featured\";b:0;s:8:\"location\";s:174:\"ផ្លូវខេមិច សង្កាត់ព្រែកតាសិត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ។\";s:4:\"type\";s:15:\"អប់រំ\";s:6:\"status\";s:9:\"Completed\";s:5:\"image\";s:32:\"/images/projects/Thumbnail-8.jpg\";s:7:\"summary\";s:597:\"ការសាងសង់សាលាជាតិគយ និងរដ្ឋាករនៃអគ្គនាយកដ្ឋានគយ និងរដ្ឋបាលកម្ពុជា គឺជាគម្រោងសាងសង់ គីមម៉ិច សម្រាប់អគ្គនាយកដ្ឋានគយ និងរដ្ឋាករកម្ពុជា ដែលមានទីតាំងនៅផ្លូវខេមិច សង្កាត់ព្រែកតាសិត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ..\";}i:2;a:8:{s:2:\"id\";s:10:\"project-21\";s:5:\"title\";s:206:\"ការសាងសង់អគារភូមិន្ទរដ្ឋបាល វិជ្ជាជីវៈតុលាការ និងវិទ្យាស្ថានសេដ្ឋកិច្ច\";s:8:\"featured\";b:0;s:8:\"location\";s:171:\"ភូមិតាតាស សង្កាត់ព្រែកតាសេក ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ។\";s:4:\"type\";s:15:\"អប់រំ\";s:6:\"status\";s:9:\"Completed\";s:5:\"image\";s:32:\"/images/projects/Thumbnail-8.jpg\";s:7:\"summary\";s:660:\"ការ​សាងសង់​អគារ​ភូមិន្ទ​រដ្ឋបាល​វិជ្ជាជីវៈ តុលាការ និង​សេដ្ឋកិច្ច ជា​គម្រោង​សាងសង់​របស់​ក្រុមហ៊ុន Kimmex របស់​ក្រសួង​សេដ្ឋកិច្ច និង​ហិរញ្ញវត្ថុ ដែល​មាន​ទីតាំង​នៅ​ភូមិ​តា​តា​សេក សង្កាត់​ព្រែក​តា​សេក ខណ្ឌ​ជ្រោយចង្វារ រាជធានី​ភ្នំពេញ..\";}i:3;a:8:{s:2:\"id\";s:10:\"project-20\";s:5:\"title\";s:108:\"គម្រោងសាងសង់មន្ទីរពេទ្យបង្អែកជ័យជំនះ\";s:8:\"featured\";b:0;s:8:\"location\";s:67:\"ក្រុងតាខ្មៅ ខេត្តកណ្តាល\";s:4:\"type\";s:27:\"សុខាភិបាល\";s:6:\"status\";s:9:\"Completed\";s:5:\"image\";s:33:\"/images/projects/dambe-clinic.jpg\";s:7:\"summary\";s:445:\"គម្រោង​សាងសង់​មន្ទីរពេទ្យ​បង្អែក​ជ័យជំនះ ជា​គម្រោង​សាងសង់​គីមម៉ិច​របស់​ក្រសួង​សេដ្ឋកិច្ច និង​ហិរញ្ញវត្ថុ ដែល​មាន​ទីតាំង​ក្នុង​ក្រុង​តាខ្មៅ ខេត្តកណ្តាល។\";}i:4;a:8:{s:2:\"id\";s:10:\"project-19\";s:5:\"title\";s:114:\"