ed\";b:0;s:8:\"location\";s:82:\"ស្រុកស្ទឹងហាវ ខេត្តព្រះសីហនុ\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:6:\"status\";s:7:\"Ongoing\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";s:7:\"summary\";s:649:\"ការដ្ឋានសាងសង់អគាររដ្ឋបាល និងហេដ្ឋារចនាសម្ព័ន្ធផ្សេងៗ នៅមជ្ឈមណ្ឌលស្តុកផលិតផលតេលា ខេត្តព្រះសីហនុ នៃនាយកដ្ឋានគយ (ស្ទឹងហាវ) គឺជាគម្រោងសាងសង់ Kimmex សម្រាប់អគ្គនាយកដ្ឋានគយ និងរដ្ឋាករកម្ពុជា ដែលមានទីតាំងនៅស្រុកស្ទឹងហាវ ខេត្តព្រះសីហនុ។\";}i:16;a:8:{s:2:\"id\";s:10:\"project-07\";s:5:\"title\";s:272:\"ការសាងសង់សាឡាង ឃ្លាំង ប៉ុស្តិ៍គយ\n និងហេដ្ឋារចនាសម្ព័ន្ធផ្សេងៗទៀតនៅការិយាល័យគយ និងរដ្ឋាករជ្រៃធំ\";s:8:\"featured\";b:0;s:8:\"location\";s:92:\"ឃុំជ្រៃធំ ស្រុកស្អាង ខេត្តកណ្តាល\";s:4:\"type\";s:54:\"ហេដ្ឋារចនាសម្ព័ន្ធ\";s:6:\"status\";s:7:\"Ongoing\";s:5:\"image\";s:37:\"/images/projects/mondulkiri-water.jpg\";s:7:\"summary\";s:663:\"ការសាងសង់សាឡាង ឃ្លាំងស្តុកទំនិញ ប៉ុស្តិ៍ត្រួតពិនិត្យគយ\n និងហេដ្ឋារចនាសម្ព័ន្ធផ្សេងទៀត នៅការិយាល័យគយ និងរដ្ឋាករជ្រៃធំ គឺជាគម្រោងសាងសង់គីមម៉ិច សម្រាប់អគ្គនាយកដ្ឋានគយ និងរដ្ឋាករកម្ពុជា ដែលមានទីតាំងនៅឃុំជ្រៃធំ ស្រុកស្អាង ខេត្តកណ្តាល។\";}i:17;a:8:{s:2:\"id\";s:17:\"project-06-def-pp\";s:5:\"title\";s:97:\"មន្ទីរសេដ្ឋកិច្ចរាជធានីភ្នំពេញ DEF-PP\";s:8:\"featured\";b:1;s:8:\"location\";s:140:\"សង្កាត់ព្រែកតាសិត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:6:\"status\";s:9:\"Completed\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";s:7:\"summary\";s:443:\"មន្ទីរសេដ្ឋកិច្ចរាជធានីភ្នំពេញ DEF-PP គឺជាគម្រោងសាងសង់ Kimmex របស់ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ ដែលមានទីតាំងនៅសង្កាត់ព្រែកតាសេត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ។\";}i:18;a:8:{s:2:\"id\";s:19:\"project-05-gdce-shv\";s:5:\"title\";s:88:\"គយ និងរដ្ឋាករក្រុងព្រះសីហនុ GDCE-SHV\";s:8:\"featured\";b:1;s:8:\"location\";s:142:\"ផ្លូវផែ ភូមិ៣ សង្កាត់៣ ខណ្ឌមិត្តភាព ក្រុងព្រះសីហនុ\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:6:\"status\";s:7:\"Ongoing\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";s:7:\"summary\";s:477:\"សាខាគយ និងរដ្ឋាករក្រុងព្រះសីហនុ GDCE-SHV គឺជាគម្រោងសាងសង់គីមម៉ិច សម្រាប់អគ្គនាយកដ្ឋានគយ និងរដ្ឋាករកម្ពុជា ដែលមានទីតាំងនៅផ្លូវផែ ភូមិ៣ សង្កាត់៣ ខណ្ឌមិត្តភាព ខេត្តព្រះសីហនុ។\";}i:19;a:8:{s:2:\"id\";s:25:\"project-04-smart-building\";s:5:\"title\";s:96:\"សាកលវិទ្យាល័យភូមិន្ទភ្នំពេញ Smart Building\";s:8:\"featured\";b:1;s:8:\"location\";s:171:\"ភូមិតាតាស សង្កាត់ព្រែកតាសេក ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ។\";s:4:\"type\";s:15:\"អប់រំ\";s:6:\"status\";s:7:\"Ongoing\";s:5:\"image\";s:32:\"/images/projects/Thumbnail-8.jpg\";s:7:\"summary\";s:418:\"Royal University of Phnom Penh Smart Building ជាគម្រោងសាងសង់ គីមម៉ិច របស់សាកលវិទ្យាល័យភូមិន្ទភ្នំពេញ ដែលមានទីតាំងនៅ ភូមិតាតឹង សង្កាត់ព្រែកតាសេក ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ..\";}i:20;a:8:{s:2:\"id\";s:15:\"project-03-nspc\";s:5:\"title\";s:122:\"អគារការិយាល័យក្រុមប្រឹក្សាសន្តិសុខសង្គម NSPC\";s:8:\"featured\";b:1;s:8:\"location\";s:174:\"ផ្លូវខេមិច សង្កាត់ព្រែកតាសិត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ។\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:6:\"status\";s:7:\"Ongoing\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";s:7:\"summary\";s:508:\"អគារការិយាល័យក្រុមប្រឹក្សាសន្តិសុខសង្គម NSPC គឺជាគម្រោងសាងសង់ គីមម៉ិច សម្រាប់ក្រុមប្រឹក្សាគាំពារសង្គម NSPC ដែលមានទីតាំងនៅផ្លូវខេមិច សង្កាត់ព្រែកតាសិត ខណ្ឌជ្រោយចង្វារ រាជធានីភ្នំពេញ..\";}i:21;a:8:{s:2:\"id\";s:18:\"project-02-nbfsa-i\";s:5:\"title\";s:152:\"NBFSA-I អគារការិយាល័យអាជ្ញាធរសេវាហិរញ្ញវត្ថុមិនមែនធនាគារ\";s:8:\"featured\";b:1;s:8:\"location\";s:193:\"អគារលេខ១៦៨ ផ្លូវ៥៩៨ សង្កាត់ច្រាំងចំរេះ១ ខណ្ឌឬស្សីកែវ រាជធានីភ្នំពេញ\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:6:\"status\";s:7:\"Ongoing\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";s:7:\"summary\";s:400:\"NBFSA-I Non-Banking Office Authority Building គឺជាគម្រោងសាងសង់របស់ Kimmex សម្រាប់ NBFSA Non-Banking Services Authority ដែលមានទីតាំងនៅអគារលេខ 168 ផ្លូវ 598 សង្កាត់ច្រាំងចំរេះ 1 ខណ្ឌឬស្សីកែវ រាជធានីភ្នំពេញ។\";}i:22;a:8:{s:2:\"id\";s:17:\"project-01-mef-09\";s:5:\"title\";s:94:\"អគារការិយាល័យក្រសួងសេដ្ឋកិច្ច MEF-09\";s:8:\"featured\";b:1;s:8:\"location\";s:169:\"អគារលេខ៦០ ផ្លូវ៩២ សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ\";s:4:\"type\";s:30:\"រដ្ឋាភិបាល\";s:6:\"status\";s:7:\"Ongoing\";s:5:\"image\";s:31:\"/images/projects/mpt-office.jpg\";s:7:\"summary\";s:495:\"អគារការិយាល័យក្រសួងសេដ្ឋកិច្ច MEF-09 គឺជាគម្រោងសាងសង់ គីមម៉ិច របស់ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ ដែលមានទីតាំងនៅអគារលេខ ៦០ ផ្លូវលេខ ៩២ សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ។\";}}}',1780514155),
