('kim-mex-construction-investment-coltd-cache-system_setting_brand_identity','a:5:{s:8:\"ceo_name\";s:16:\"Okhna. TOUCH KIM\";s:16:\"about_hero_image\";s:0:\"\";s:20:\"about_section_images\";a:4:{i:0;s:0:\"\";i:1;s:0:\"\";i:2;s:0:\"\";i:3;s:0:\"\";}s:2:\"en\";a:6:{s:13:\"company_story\";s:382:\"Established in 1999, Kim Mex Construction & Investment Co., Ltd. is a deeply respected and duly registered enterprise in the Kingdom of Cambodia. Over more than 25 years, we have evolved from a specialized engineering firm into a premier multi-disciplinary construction partner, delivering iconic infrastructure that stands the test of time while elevating the communities we serve.\";s:11:\"ceo_message\";s:159:\"<p>Construction is not just about concrete and steel. It is about building trust, fostering communities, and leaving a legacy that stands the test of time.</p>\";s:7:\"mission\";s:135:\"To bridge the gap between concept and reality through exceptional precision, military-grade safety, and sustainable building practices.\";s:6:\"vision\";s:141:\"To be the most trusted and innovative construction partner in Cambodia, setting the benchmark for excellence in architecture and engineering.\";s:4:\"goal\";s:136:\"To maintain long-term leadership in the Cambodian market through talent development, CMS investment, and a zero-accident safety records.\";s:11:\"values_list\";a:7:{i:0;a:4:{s:5:\"title\";s:7:\"HONESTY\";s:11:\"description\";s:71:\"Unwavering transparency and ethics in every contract and communication.\";s:4:\"icon\";s:13:\"lucide-shield\";s:5:\"image\";N;}i:1;a:4:{s:5:\"title\";s:10:\"DISCIPLINE\";s:11:\"description\";s:67:\"Military-grade precision and adherence to strict project timelines.\";s:4:\"icon\";s:12:\"lucide-award\";s:5:\"image\";N;}i:2;a:4:{s:5:\"title\";s:13:\"QUALITY FIRST\";s:11:\"description\";s:67:\"Rigorous international standards applied from foundation to finish.\";s:4:\"icon\";s:21:\"lucide-check-circle-2\";s:5:\"image\";N;}i:3;a:4:{s:5:\"title\";s:18:\"CULTURE OF SHARING\";s:11:\"description\";s:60:\"Fostering knowledge exchange to empower our local workforce.\";s:4:\"icon\";s:14:\"lucide-share-2\";s:5:\"image\";N;}i:4;a:4:{s:5:\"title\";s:23:\"CREATIVITY & INNOVATION\";s:11:\"description\";s:72:\"Pioneering new construction techniques and modern architectural designs.\";s:4:\"icon\";s:16:\"lucide-lightbulb\";s:5:\"image\";N;}i:5;a:4:{s:5:\"title\";s:27:\"RESPECT THE VALUE OF PEOPLE\";s:11:\"description\";s:75:\"Putting the safety and dignity of our staff at the heart of our operations.\";s:4:\"icon\";s:12:\"lucide-users\";s:5:\"image\";N;}i:6;a:4:{s:5:\"title\";s:18:\"SENSE OF OWNERSHIP\";s:11:\"description\";s:79:\"Every team member takes personal pride and responsibility for every brick laid.\";s:4:\"icon\";s:10:\"lucide-key\";s:5:\"image\";N;}}}s:2:\"km\";a:6:{s:13:\"company_story\";s:1047:\"បង្កើតឡើងក្នុងឆ្នាំ 1999 ក្រុមហ៊ុន គីម ម៉ិច ខនស្ត្រាសិន និង អ៊ិនវេសមេន ខូអិលធីឌី គឺជាសហគ្រាសដែលមានការចុះបញ្ជីត្រឹមត្រូវ និងគោរពយ៉ាងជ្រាលជ្រៅនៅក្នុងព្រះរាជាណាចក្រកម្ពុជា។ ក្នុងរយៈពេលជាង 25 ឆ្នាំ យើងបានវិវត្តន៍ពីក្រុមហ៊ុនវិស្វកម្មឯកទេសទៅជាដៃគូសាងសង់ពហុវិន័យឈានមុខគេ ដោយផ្តល់នូវហេដ្ឋារចនាសម្ព័ន្ធរូបសញ្ញាដែលឈរលើការសាកល្បងនៃពេលវេលាខណៈពេលដែលលើកកម្ពស់សហគមន៍ដែលយើងបម្រើ។\";s:11:\"ceo_message\";s:437:\"<p>ការ​សាង​សង់​មិន​មែន​ត្រឹម​តែ​បេតុង និង​ដែក​នោះ​ទេ។ វានិយាយអំពីការកសាងទំនុកចិត្ត ពង្រឹងសហគមន៍ និងការបន្សល់ទុកនូវកេរដំណែលដែលឈរលើការសាកល្បងនៃពេលវេលា។</p>\";s:7:\"mission\";s:355:\"ដើម្បីភ្ជាប់គម្លាតរវាងគំនិត និងការពិត តាមរយៈភាពជាក់លាក់ពិសេស សុវត្ថិភាពកម្រិតយោធា និងការអនុវត្តការកសាងប្រកបដោយនិរន្តរភាព។\";s:6:\"vision\";s:423:\"ដើម្បីធ្វើជាដៃគូសាងសង់ប្រកបដោយភាពជឿជាក់ និងច្នៃប្រឌិតបំផុតនៅក្នុងប្រទេសកម្ពុជា កំណត់ស្តង់ដារសម្រាប់ឧត្តមភាពក្នុងវិស័យស្ថាបត្យកម្ម និងវិស្វកម្ម។\";s:4:\"goal\";s:403:\"ដើម្បីរក្សាភាពជាអ្នកដឹកនាំរយៈពេលវែងនៅក្នុងទីផ្សារកម្ពុជា តាមរយៈការអភិវឌ្ឍន៍ទេពកោសល្យ ការវិនិយោគ CMS និងកំណត់ត្រាសុវត្ថិភាពគ្មានគ្រោះថ្នាក់។\";s:11:\"values_list\";a:7:{i:0;a:4:{s:5:\"title\";s:39:\"ភាពស្មោះត្រង់\";s:11:\"description\";s:212:\"តម្លាភាព និងក្រមសីលធម៌មិនផ្លាស់ប្តូរនៅក្នុងរាល់កិច្ចសន្យា និងទំនាក់ទំនង។\";s:4:\"icon\";s:13:\"lucide-shield\";s:5:\"image\";N;}i:1;a:4:{s:5:\"title\";s:15:\"វិន័យ\";s:11:\"description\";s:220:\"ភាពជាក់លាក់ថ្នាក់យោធា និងការប្រកាន់ខ្ជាប់នូវការកំណត់ពេលវេលាគម្រោងដ៏តឹងរឹង។\";s:4:\"icon\";s:12:\"lucide-award\";s:5:\"image\";N;}i:2;a:4:{s:5:\"title\";s:33:\"គុណភាពដំបូង\";s:11:\"description\";s:181:\"ស្តង់ដារអន្តរជាតិយ៉ាងម៉ត់ចត់ អនុវត្តតាំងពីមូលដ្ឋានរហូតដល់ចប់។\";s:4:\"icon\";s:21:\"lucide-check-circle-2\";s:5:\"image\";N;}i:3;a:4:{s:5:\"title\";s:60:\"វប្បធម៌នៃការចែករំលែក\";s:11:\"description\";s:211:\"ជំរុញការផ្លាស់ប្តូរចំណេះដឹង ដើម្បីពង្រឹងកម្លាំងពលកម្មក្នុងស្រុករបស់យើង។\";s:4:\"icon\";s:14:\"lucide-share-2\";s:5:\"image\";N;}i:4;a:4:{s:5:\"title\";s:94:\"ភាពច្នៃប្រឌិត និងគំនិតច្នៃប្រឌិត\";s:11:\"description\";s:175:\"ត្រួសត្រាយលើបច្ចេកទេសសំណង់ថ្មី និងការរចនាស្ថាបត្យកម្មទំនើប។\";s:4:\"icon\";s:16:\"lucide-lightbulb\";s:5:\"image\";N;}i:5;a:4:{s:5:\"title\";s:57:\"គោរពតម្លៃរបស់មនុស្ស\";s:11:\"description\";s:266:\"ការដាក់សុវត្ថិភាព និងសេចក្តីថ្លៃថ្នូររបស់បុគ្គលិករបស់យើង គឺជាបេះដូងនៃប្រតិបត្តិការរបស់យើង។\";s:4:\"icon\";s:12:\"lucide-users\";s:5:\"image\";N;}i:6;a:4:{s:5:\"title\";s:63:\"អារម្មណ៍នៃភាពជាម្ចាស់\";s:11:\"description\";s:226:\"សមាជិកក្រុមនីមួយៗមានមោទនភាព និងទំនួលខុសត្រូវផ្ទាល់ខ្លួនចំពោះរាល់ឥដ្ឋដែលដាក់។\";s:4:\"icon\";s:10:\"lucide-key\";s:5:\"image\";N;}}}}',2095831519),
