('019e8c55-4cd9-72d9-89d3-ab307ff29f43','{\"en\":\"Project Management\",\"km\":\"ការគ្រប់គ្រងគម្រោង\"}','project-mgmt','{\"en\":\"KIMMEX Project Management Department\",\"km\":\"នាយកដ្ឋាន ការគ្រប់គ្រងគម្រោង របស់ក្រុមហ៊ុន គីម ម៉ិច\"}','2026-06-03 00:14:21','2026-06-03 00:14:21',1),
