INSERT INTO `job_postings` VALUES
('019e8c55-4cb4-7312-9c42-d61fd48c9777','{\"en\":\"Senior Project Manager\",\"km\":\"អ្នកគ្រប់គ្រងគម្រោងជាន់ខ្ពស់\"}','senior-project-manager',NULL,'{\"en\":\"Phnom Penh\",\"km\":\"ភ្នំពេញ\"}','FULL_TIME','{\"en\":\"Leading large-scale construction projects from inception to completion.\",\"km\":\"ដឹកនាំគម្រោងសាងសង់ខ្នាតធំចាប់ពីការចាប់ផ្តើមរហូតដល់ការបញ្ចប់។\"}','{\"en\":\"Bachelor\'s degree in Civil Engineering.\\nStrong leadership and communication skills.\\nProficiency in project management software.\",\"km\":\"បរិញ្ញាបត្រផ្នែកវិស្វកម្មស៊ីវិល។\\nជំនាញដឹកនាំនិងទំនាក់ទំនងខ្លាំង។\\nជំនាញក្នុងកម្មវិធីគ្រប់គ្រងគម្រោង។\"}','{\"en\":\"Health insurance.\\nPerformance bonuses.\\nProfessional development opportunities.\",\"km\":\"ធានារ៉ាប់រងសុខភាព។\\nប្រាក់រង្វាន់ការងារ។\\nឱកាសអភិវឌ្ឍន៍វិជ្ជាជីវៈ។\"}',1,NULL,'{\"en\":\"5-10 Years\",\"km\":\"៥-១០ ឆ្នាំ\"}','{\"en\":\"Competitive\",\"km\":\"ប្រកួតប្រជែង\"}','{\"en\":\"Manage project budgets and timelines.\\nCoordinate with subcontractors and engineers.\\nEnsure safety and quality compliance.\",\"km\":\"<ul><li>គ្រប់គ្រងថវិកានិងពេលវេលាគម្រោង។</li><li>សម្របសម្រួលជាមួយអ្នកម៉ៅការបន្តនិងវិស្វករ។</li><li>ធានាបាននូវការអនុលោមតាមសុវត្ថិភាពនិងគុណភាព។</li></ul>\"}','2026-06-03 00:14:20','2026-06-03 00:14:20'),
('019e8c55-4cb9-7281-9e46-4797e368820e','{\"en\":\"Site Engineer\",\"km\":\"វិស្វករការដ្ឋាន\"}','site-engineer',NULL,'{\"en\":\"Siem Reap\",\"km\":\"សៀមរាប\"}','FULL_TIME','{\"en\":\"Overseeing day-to-day operations on construction sites.\",\"km\":\"ត្រួតពិនិត្យប្រតិបត្តិការប្រចាំថ្ងៃនៅការដ្ឋានសំណង់។\"}','{\"en\":\"Degree in Civil Engineering or related field.\\nPractical experience in site supervision.\\nProblem-solving mindset.\",\"km\":\"សញ្ញាបត្រផ្នែកវិស្វកម្មស៊ីវិលឬជំនាញពាក់ព័ន្ធ។\\nបទពិសោធន៍ជាក់ស្តែងក្នុងការត្រួតពិនិត្យការដ្ឋាន។\\nផ្នត់គំនិតដោះស្រាយបញ្ហា។\"}','{\"en\":\"Accommodation allowance.\\nSkills training.\\nCareer growth track.\",\"km\":\"ប្រាក់ឧបត្ថម្ភការស្នាក់នៅ។\\nការបណ្តុះបណ្តាលជំនាញ។\\nផ្លូវកំណើនអាជីព។\"}',1,NULL,'{\"en\":\"2-5 Years\",\"km\":\"២-៥ ឆ្នាំ\"}','{\"en\":\"Negotiable\",\"km\":\"ចរចា\"}','{\"en\":\"Supervise site labor and subcontractors.\\nTechnical review of architectural blueprints.\\nReport progress to Project Managers.\",\"km\":\"<ul><li>ត្រួតពិនិត្យកម្លាំងពលកម្មនិងអ្នកម៉ៅការបន្ត។</li><li>ពិនិត្យបច្ចេកទេសលើប្លង់ស្ថាបត្យកម្ម។</li><li>រាយការណ៍វឌ្ឍនភាពទៅអ្នកគ្រប់គ្រងគម្រោង។</li></ul>\"}','2026-06-03 00:14:20','2026-06-03 00:14:20');
/*!40000 ALTER TABLE `job_postings` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
