INSERT INTO `milestones` VALUES
('019e8c55-4c8b-721b-9669-f68a5ff0aa4a','1999','{\"en\":\"Foundation\",\"km\":\"ការបង្កើតឡើង\"}','{\"en\":\"<p>Kim Mex Construction & Investment Co.,Ltd. was established and registered in accordance with the regulations and laws of the Kingdom of Cambodia.</p>\",\"km\":\"<p>ក្រុមហ៊ុន Kim Mex Construction & Investment Co.,Ltd. ត្រូវបានបង្កើតឡើង និងចុះបញ្ជីស្របតាមបទប្បញ្ញត្តិ និងច្បាប់នៃព្រះរាជាណាចក្រកម្ពុជា។</p>\"}','images/projects/Thumbnail-1.jpg',10,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4c8e-73c0-8525-05e4c5dfc975','2001-2004','{\"en\":\"Early Growth\",\"km\":\"កំណើនដំបូង\"}','{\"en\":\"<p>Laying the groundwork for excellence in provincial infrastructure and building quality partnerships across the kingdom.</p>\",\"km\":\"<p>ការរៀបចំមូលដ្ឋានគ្រឹះសម្រាប់ឧត្តមភាពនៅក្នុងហេដ្ឋារចនាសម្ព័ន្ធខេត្ត និងការកសាងភាពជាដៃគូប្រកបដោយគុណភាពនៅទូទាំងព្រះរាជាណាចក្រកម្ពុជា។</p>\"}','images/projects/Thumbnail-2.jpg',20,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4c92-71f2-b6e8-16471baa1939','2005-2013','{\"en\":\"Expanding Horizons\",\"km\":\"ការពង្រីកវិសាលភាព\"}','{\"en\":\"<p>Significant expansion of services into specialized building construction and large-scale public utility projects.</p>\",\"km\":\"<p>ការពង្រីកសេវាកម្មយ៉ាងសំខាន់ទៅក្នុងការសាងសង់អគារឯកទេស និងគម្រោងហេដ្ឋារចនាសម្ព័ន្ធសាធារណៈខ្នាតធំ។</p>\"}','images/projects/Thumbnail-3.jpg',30,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4c94-7028-90ee-426ad4a340bd','2014-2017','{\"en\":\"Institutional Partnerships\",\"km\":\"ភាពជាដៃគូស្ថាប័ន\"}','{\"en\":\"<p>Delivery of key institutional projects including:</p><ol><li>Ministry of Economy and Finance</li><li>Ministry of Post and Telecommunication</li><li>Clean Water in Mondulkiri Province</li><li>Electricity of Cambodia Wat Phnom</li><li>Al Serkal Mosque</li></ol>\",\"km\":\"<p>ការប្រគល់គម្រោងស្ថាប័នសំខាន់ៗរួមមាន៖</p><ol><li>ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ</li><li>ក្រសួងប្រៃសណីយ៍ និងទូរគមនាគមន៍</li><li>ទឹកស្អាតខេត្តមណ្ឌលគិរី</li><li>អគ្គិសនីកម្ពុជា វត្តភ្នំ</li><li>វិហារអ៊ីស្លាម អាល់សឺកាល់</li></ol>\"}','images/projects/Thumbnail-4.jpg',40,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4c98-7133-9c08-7f5392afba2d','2018-2020','{\"en\":\"Scaling Innovation\",\"km\":\"ការពង្រីកនវានុវត្តន៍\"}','{\"en\":\"<p>Integration of modern systems and complex structural works:</p><ol><li>Anti-Corruption Unit</li><li>Siem Reap Electricity</li><li>Ministry of Economy Underground Parking Lot</li><li>General Department of National Treasury</li></ol>\",\"km\":\"<p>ការរួមបញ្ចូលនៃប្រព័ន្ធទំនើប និងការអនុវត្តរចនាសម្ព័ន្ធស្មុគស្មាញ៖</p><ol><li>អង្គភាពប្រឆាំងអំពើពុករលួយ</li><li>អគ្គិសនីខេត្តសៀមរាប</li><li>ចំណតឡានក្រោមដីក្រសួងសេដ្ឋកិច្ច</li><li>អគ្គនាយកដ្ឋានរតនាគារជាតិ</li></ol>\"}','images/projects/Thumbnail-5.jpg',50,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4c9a-705e-a19d-ccbff9a64b94','2021-2022','{\"en\":\"Infrastructure Excellence\",\"km\":\"ឧត្តមភាពហេដ្ឋារចនាសម្ព័ន្ធ\"}','{\"en\":\"<p>Securing major national landmarks and utility hubs:</p><ol><li>Stung Treng Water Purification Station</li><li>General Department of Customs and Excise of Cambodia</li><li>Securities and Exchange Commission of Cambodia</li><li>Electricity of Cambodia</li></ol>\",\"km\":\"<p>សាងសង់ហេដ្ឋារចនាសម្ព័ន្ធសំខាន់ៗ និងមជ្ឈមណ្ឌលអគ្គិសនីជាតិ៖</p><ol><li>ស្ថានីយ៍ប្រព្រឹត្តិកម្មទឹកស្អាតខេត្តស្ទឹងត្រែង</li><li>អគ្គនាយកដ្ឋានគយ និងរដ្ឋាករកម្ពុជា</li><li>គណៈកម្មការមូលបត្រកម្ពុជា</li><li>អគ្គិសនីកម្ពុជា (EDC)</li></ol>\"}','images/projects/Thumbnail-6.jpg',60,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4c9e-7277-b515-09f8743ed735','2023','{\"en\":\"Strategic Progress\",\"km\":\"វឌ្ឍនភាពយុទ្ធសាស្ត្រ\"}','{\"en\":\"<p>Completion of high-profile government headquarters:</p><ol><li>Ministry of Interior</li><li>National Social Security Fund</li></ol>\",\"km\":\"<p>ការបញ្ចប់អគារទីស្នាក់ការកណ្តាលរបស់រដ្ឋាភិបាល៖</p><ol><li>ក្រសួងមហាផ្ទៃ</li><li>បេឡាជាតិរបបសន្តិសុខសង្គម (ប.ស.ស)</li></ol>\"}','images/projects/Thumbnail-7.jpg',70,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4ca3-7043-8ea2-9723628eb84c','2024','{\"en\":\"Future Foundations\",\"km\":\"មូលដ្ឋានគ្រឹះអនាគត\"}','{\"en\":\"<p>Expanding into healthcare and regulatory sectors:</p><ol><li>Commercial Gambling Management Commission of Cambodia</li><li>Chey Chumneas Hospital</li></ol>\",\"km\":\"<p>ការពង្រីកខ្លួនចូលក្នុងវិស័យថែទាំសុខភាព និងបទប្បញ្ញត្តិ៖</p><ol><li>គណៈកម្មការគ្រប់គ្រងល្បែងពាណិជ្ជកម្មកម្ពុជា</li><li>មន្ទីរពេទ្យ ជ័យជំនះ</li></ol>\"}','images/projects/Thumbnail-8.jpg',80,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL),
('019e8c55-4ca6-7003-8e61-95ecf6817405','2025','{\"en\":\"Vision 2025\",\"km\":\"ចក្ខុវិស័យ ២០២៥\"}','{\"en\":\"<p>Ongoing and future flagship developments:</p><ol><li>National Election Committee</li></ol>\",\"km\":\"<p>ការអភិវឌ្ឍកំពុងបន្ត និងគម្រោងសំខាន់ៗនាពេលអនាគត៖</p><ol><li>គណៈកម្មាធិការជាតិរៀបចំការបោះឆ្នោត</li></ol>\"}','images/projects/Thumbnail-9.jpg',90,'2026-06-03 00:14:20','2026-06-03 00:14:20',1,NULL);
/*!40000 ALTER TABLE `milestones` ENABLE KEYS */;
