--
-- Table structure for table `projects`
--

DROP TABLE IF EXISTS `projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `projects` (
  `id` char(36) NOT NULL,
  `title` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`title`)),
  `slug` varchar(255) NOT NULL,
  `category` varchar(255) DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'ONGOING',
  `location` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`location`)),
  `client` varchar(255) DEFAULT NULL,
  `completionDate` timestamp NULL DEFAULT NULL,
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`description`)),
  `heroImage` varchar(255) DEFAULT NULL,
  `isFeatured` tinyint(1) NOT NULL DEFAULT 0,
  `isActive` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `project_category_id` bigint(20) unsigned DEFAULT NULL,
  `background` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`background`)),
  `objectives` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`objectives`)),
  `designConcept` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`designConcept`)),
  `scopeContributions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`scopeContributions`)),
  `engineeringNarrative` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`engineeringNarrative`)),
  `timeline` varchar(255) DEFAULT NULL,
  `scale` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `projects_slug_unique` (`slug`),
  KEY `projects_project_category_id_foreign` (`project_category_id`),
  KEY `idx_projects_slug` (`slug`),
  KEY `idx_projects_active` (`isActive`),
  CONSTRAINT `projects_project_category_id_foreign` FOREIGN KEY (`project_category_id`) REFERENCES `project_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `projects`
--

SET @OLD_AUTOCOMMIT=@@AUTOCOMMIT, @@AUTOCOMMIT=0;
LOCK TABLES `projects` WRITE;
/*!40000 ALTER TABLE `projects` DISABLE KEYS */;
INSERT INTO `projects` VALUES
('019e8c54-79a7-70f2-827a-4880a64a05a6','{\"en\":\"Ministry of Economy Office Building MEF-09\",\"km\":\"អគារការិយាល័យក្រសួងសេដ្ឋកិច្ច MEF-09\"}','project-01-mef-09','government','ONGOING','{\"en\":\"Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh\",\"km\":\"អគារលេខ៦០ ផ្លូវ៩២ សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ\"}','Ministry of Economy and Finance','2026-06-30 17:00:00','{\"en\":\"<p>Ministry of Economy Office Building MEF-09 is a Kimmex construction project for Ministry of Economy and Finance, located in Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh.</p>\",\"km\":\"<p>អគារការិយាល័យក្រសួងសេដ្ឋកិច្ច MEF-09 គឺជាគម្រោងសាងសង់ គីមម៉ិច របស់ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ ដែលមានទីតាំងនៅអគារលេខ ៦០ ផ្លូវលេខ ៩២ សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ។</p>\"}','/images/projects/mpt-office.jpg',1,1,'2026-06-03 00:13:26','2026-06-03 00:13:26',2,'{\"en\":\"<p>The project was planned around the client requirements, site conditions, and construction schedule for Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh.</p><ul><li>Construction value: $3,650,000.00</li><li>Built area: 3,563 m²</li><li>Planned duration: 14 months</li></ul>\",\"km\":\"<p>គម្រោងនេះត្រូវបានគ្រោងទុកជុំវិញតម្រូវការអតិថិជន លក្ខខណ្ឌការដ្ឋាន និងកាលវិភាគសាងសង់សម្រាប់អគារលេខ 60 ផ្លូវលេខ 92 សង្កាត់វត្តភ្នំ ខណ្ឌដូនពេញ រាជធានីភ្នំពេញ។</p><ul><li>តម្លៃសាងសង់៖ $3,650,000.00</li><li>ផ្ទៃដីសាងសង់៖ 3,563 m²</li><li>14li>Planned: រយៈពេល៖\"}','{\"en\":\"<ul><li>Deliver the project scope with practical coordination between client, design, and site teams.</li><li>Maintain construction quality, schedule discipline, and safe site execution.</li><li>Provide a durable facility that supports the operational needs of Ministry of Economy and Finance.</li></ul>\",\"km\":\"<ul><li>ផ្តល់វិសាលភាពគម្រោងដោយមានការសម្របសម្រួលជាក់ស្តែងរវាងអតិថិជន ការរចនា និងក្រុមគេហទំព័រ។</li><li>រក្សាគុណភាពសំណង់ ការកំណត់កាលវិភាគ និងការអនុវត្តទីតាំងប្រកបដោយសុវត្ថិភាព។</li><li>ផ្តល់កន្លែងប្រើប្រាស់បានយូរ ដែលគាំទ្រដល់តម្រូវការប្រតិបត្តិការរបស់ក្រសួងសេដ្ឋកិច្ច និងហិរញ្ញវត្ថុ។</li></ul>\"}','{\"en\":\"<p>The design and construction approach focused on institutional function, public access, and long-term durability. Kimmex aligned execution with the documented scale, location, and schedule requirements.</p>\",\"km\":\"<p>វិធីសាស្រ្តនៃការរចនា និងការសាងសង់ផ្តោតលើមុខងារស្ថាប័ន ការចូលប្រើប្រាស់ជាសាធារណៈ និងយូរអង្វែង។ Kimmex បាន​តម្រឹម​ការ​ប្រតិបត្តិ​តាម​ខ្នាត​ឯកសារ ទីតាំង និង​តម្រូវការ​កាលវិភាគ។</p>\"}','{\"en\":\"<ul><li>Project owner: Ministry of Economy and Finance</li><li>Construction location: Building No. 60, Street 92, Sangkat Wat Phnom, Khan Daun Penh, Phnom Penh</li><li>Construction value: $3,650,000.00</li><li>Built area: 3,563 m²</li><li>Floors: 6 floors</li><li>Duration: 14 months</li></ul>\",\"km\":\"<ul><li>ម្ចាស់គម្រោង: ក្រសួងសេដ្ខកិច្ច និង ហរិញ្ញវត្ថុ</li><li>ទីតាំងសាងសង់: អគារលេខ ៦០, ផ្លូវលេខ ៩២, សង្កាត់វត្តភ្នំ, ខណ្ឌដូនពេញ, រាជធានីភ្នំពេញ</li><li>តម្លៃសាងសង់: $3,650,000.00</li><li>ផ្ទៃក្រឡា: 3,563 m²</li><li>ចំនួនជាន់: 6ជាន់</li><li>រយៈពេល: 14 ខែ</li></ul>\"}','{\"en\":\"<p>Kimmex managed construction execution through practical sequencing, site coordination, and quality checks across the project lifecycle.</p><p>The work required coordination of resources, materials, and schedule milestones to keep delivery aligned with client expectations.</p>\",\"km\":\"<p>Kimmex បានគ្រប់គ្រងការប្រតិបត្តិសំណង់តាមរយៈការអនុវត្តតាមលំដាប់លំដោយជាក់ស្តែង ការសំរបសំរួលទីតាំង និងការត្រួតពិនិត្យគុណភាពនៅទូទាំងវដ្តជីវិតរបស់គម្រោង។\"}','May 2025 - Jul 2026','6 floors | 3,563 m²'),
('019e8c54-81c5-715d-b2aa-48627c13d0a8','{\"en\":\"NBFSA-I Non-Banking Financial Services Authority Office Building\",\"km\":\"NBFSA-I អគារការិយាល័យអាជ្ញាធរសេវាហិរញ្ញវត្ថុមិនមែនធនាគារ\"}','project-02-nbfsa-i','government','ONGOING','{\"en\":\"Building No. 168, Street 598, Sangkat Chrang Chamres 1, Khan Russey Keo, Phnom Penh\",\"km\":\"អគារលេខ១៦៨ ផ្លូវ៥៩៨ សង្កាត់ច្រាំងចំរេះ១ ខណ្ឌឬស្សីកែវ រាជធានីភ្នំពេញ\"}','NBFSA Non-Banking Financial Services Authority','2026-10-31 17:00:00','{\"en\":\"<p>NBFSA-I Non-Banking Financial Services Authority Office Building is a Kimmex construction project for NBFSA Non-Banking Financial Services Authority, located in Building No. 168, Street 598, Sangkat Chrang Chamres 1, Khan Russey Keo, Phnom Penh.</p>\",\"km\":\"<p>NBFSA-I Non-Banking Office Authority Building គឺជាគម្រោងសាងសង់របស់ Kimmex សម្រាប់ NBFSA Non-Banking Services Authority ដែលមានទីតាំងនៅអគារលេខ 168 ផ្លូវ 598 សង្កាត់ច្រាំងចំរេះ 1 ខណ្ឌឬស្សីកែវ រាជធានីភ្នំពេញ។</p>\"}','/images/projects/mpt-office.jpg',1,1,'2026-06-03 00:13:29','2026-06-03 00:13:29',2,'{\"en\":\"<p>The project was planned around the client requirements, site conditions, and construction schedule for Building No. 168, Street 598, Sangkat Chrang Chamres 1, Khan Russey Keo, Phnom Penh.</p><ul><li>Construction value: $4,930,000.00</li><li>Built area: 6,900 m²</li><li>Planned duration: 22 months</li></ul>\",\"km\":\"<p>គម្រោងនេះត្រូវបានគ្រោងទុកជុំវិញតម្រូវការអតិថិជន លក្ខខណ្ឌការដ្ឋាន និងកាលវិភាគសាងសង់អគារលេខ ១៦៨ ផ្លូវ ៥៩៨ សង្កាត់ច្រាំងចំរេះ១ ខណ្ឌឫស្សីកែវ រាជធានីភ្នំពេញ។</p><ul><li>តម្លៃសាងសង់៖ $4,930,000.00</li><li>ផ្ទៃដីសាងសង់៖ 6,><900 ម៉ែត្រការ៉េ</li> 2 ខែ</li><li>\"}','{\"en\":\"<ul><li>Deliver the project scope with practical coordination between client, design, and site teams.</li><li>Maintain construction quality, schedule discipline, and safe site execution.</li><li>Provide a durable facility that supports the operational needs of NBFSA Non-Banking Financial Services Authority.</li></ul>\",\"km\":\"<ul><li>ផ្ត