('019e8c54-72ca-71fd-a529-5751727ca02a','brand_identity','{\"ceo_name\":\"Okhna. TOUCH KIM\",\"about_hero_image\":\"\",\"about_section_images\":[\"\",\"\",\"\",\"\"],\"en\":{\"company_story\":\"Established in 1999, Kim Mex Construction & Investment Co., Ltd. is a deeply respected and duly registered enterprise in the Kingdom of Cambodia. Over more than 25 years, we have evolved from a specialized engineering firm into a premier multi-disciplinary construction partner, delivering iconic infrastructure that stands the test of time while elevating the communities we serve.\",\"ceo_message\":\"<p>Construction is not just about concrete and steel. It is about building trust, fostering communities, and leaving a legacy that stands the test of time.<\\/p>\",\"mission\":\"To bridge the gap between concept and reality through exceptional precision, military-grade safety, and sustainable building practices.\",\"vision\":\"To be the most trusted and innovative construction partner in Cambodia, setting the benchmark for excellence in architecture and engineering.\",\"goal\":\"To maintain long-term leadership in the Cambodian market through talent development, CMS investment, and a zero-accident safety records.\",\"values_list\":[{\"title\":\"HONESTY\",\"description\":\"Unwavering transparency and ethics in every contract and communication.\",\"icon\":\"lucide-shield\",\"image\":null},{\"title\":\"DISCIPLINE\",\"description\":\"Military-grade precision and adherence to strict project timelines.\",\"icon\":\"lucide-award\",\"image\":null},{\"title\":\"QUALITY FIRST\",\"description\":\"Rigorous international standards applied from foundation to finish.\",\"icon\":\"lucide-check-circle-2\",\"image\":null},{\"title\":\"CULTURE OF SHARING\",\"description\":\"Fostering knowledge exchange to empower our local workforce.\",\"icon\":\"lucide-share-2\",\"image\":null},{\"title\":\"CREATIVITY & INNOVATION\",\"description\":\"Pioneering new construction techniques and modern architectural d