('019e8c55-4c65-71a7-b492-85e3c69c93fb','{\"en\":\"Sok V.\",\"km\":\"សុខ វ.\"}','{\"en\":\"CEO, Alpha Corp\",\"km\":\"នាយកប្រតិបត្តិ Alpha Corp\"}',NULL,'{\"en\":\"They delivered our commercial building ahead of schedule and with impeccable quality.\",\"km\":\"ពួកគេបានប្រគល់អគារពាណិជ្ជកម្មរបស់យើងមុនកាលវិភាគ និងមានគុណភាពឥតខ្ចោះ។\"}',5,NULL,1,1,'2026-06-03 00:14:20','2026-06-03 00:14:20',1),
('019e8c55-4c71-734e-9e77-bd7715688e89','{\"en\":\"Dr. Cham\",\"km\":\"បណ្ឌិត ចំ\"}','{\"en\":\"Director of Infrastructure\",\"km\":\"ប្រធានផ្នែកហេដ្ឋារចនាសម្ព័ន្ធ\"}',NULL,'{\"en\":\"The attention to detail and safety standards were outstanding during the water plant project.\",\"km\":\"ការយកចិត្តទុកដាក់លើព័ត៌មានលម្អិត និងស្តង់ដារសុវត្ថិភាពគឺលេចធ្លោយ៉ាងខ្លាំងក្នុងអំឡុងពេលគម្រោងរោងចក្រទឹក។\"}',5,NULL,1,2,'2026-06-03 00:14:20','2026-06-03 00:14:20',1),
('019e8c55-4c77-706b-97ee-5bf2134b4007','{\"en\":\"Mr. Rithy\",\"km\":\"លោក រិទ្ធី\"}','{\"en\":\"Property Developer\",\"km\":\"អ្នកអភិវឌ្ឍន៍អចលនទ្រព្យ\"}',NULL,'{\"en\":\"Highly professional team. They handled all the MEP complexities without a single delay.\",\"km\":\"ក្រុមការងារដែលមានវិជ្ជាជីវៈខ្ពស់។ ពួកគេបានដោះស្រាយរាល់ភាពស្មុគស្មាញនៃ MEP ដោយមិនមានការយឺតយ៉ាវសូម្បីតែម្តង។\"}',5,NULL,1,3,'2026-06-03 00:14:20','2026-06-03 00:14:20',1);
